const EXCLUDED = ['n/a', '', 'unknown'];
const formatted_reports = [];

function parseIfString(val) {
  if (!val) return {};
  if (typeof val === 'object' && !Array.isArray(val)) return val;
  let s = String(val).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(s); } catch {}
  const m = s.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch {} }
  return {};
}

function splitAndClean(text) {
  if (!text || String(text).trim().toLowerCase() === 'n/a') return 'N/A';

  const raw = String(text).replace(/\r/g, '');

  // Split on newline OR on an inline bullet char that follows a word boundary
  // This catches both "\n• item" and "sentence,• item" patterns
  const lines = raw
    .split(/\n|(?<=\S)\s*[•·\u2022]\s*/)
    .map(l => l.replace(/^[\s•·\u2022\-\*,]+/, '').trim())
    .filter(l => l.length > 0 && l.toLowerCase() !== 'n/a');

  return lines.length ? lines.join('\n') : 'N/A';
}

for (const item of items) {
  let data = item.json || {};

  if (!data.activitiesPerformed && data.output) {
    const parsed = parseIfString(data.output);
    if (parsed.reporter) data = { ...data, ...parsed };
  }

  const reporterNorm = (data.reporter || '').trim().toLowerCase();
  if (EXCLUDED.includes(reporterNorm)) continue;

  console.log(`[Format Table] Processing: ${data.reporter}`);

  formatted_reports.push({
    json: {
      reportTitle: data.reportTitle || 'Weekly Activity Report',
      programLine: data.programLine || 'Program: Operations & Maintenance Support',
      reporter:    data.reporter,
      weekEnding:  data.weekEnding || new Date().toISOString().split('T')[0],
      sections: [
        { label: 'Activities Performed',                                               content: splitAndClean(data.activitiesPerformed) },
        { label: 'Key Task/\nAccomplishments',                                         content: splitAndClean(data.tasksAccomplished) },
        { label: 'Issues & Challenges or\nwork-related concerns',                      content: splitAndClean(data.issuesChallenges) },
        { label: 'Risks or Vulnerabilities',                                           content: splitAndClean(data.risksVulnerabilities) },
        { label: 'Iterative Modernization\nand/or Process\nImprovement Opportunities', content: splitAndClean(data.processImprovementOpportunities) },
        { label: 'Additional Training,\nTools and/or Support Needs',                   content: splitAndClean(data.supportNeeds) },
        { label: 'Upcoming Activities\nfor next week',                                 content: splitAndClean(data.upcomingWeekActivities) },
        { label: 'Planned Leave',                                                      content: splitAndClean(data.plannedLeave) }
      ]
    }
  });
}

console.log(`[Format Table] Output: ${formatted_reports.length} reports`);
return formatted_reports;

const META_PATTERNS = [
  /worklog evidence not provided/i,
  /status moves? not provided/i,
  /no worklog entries?/i,
  /no changelog/i,
  /not provided\s*$/i,
];

function isMetaNote(line) {
  return META_PATTERNS.some(p => p.test(line));
}

function buildHTML(report) {
  const CSS = `
    @page { margin: 30px 40px; }
    body { font-family: Calibri, Arial, sans-serif; margin: 40px; font-size: 11pt; }
    h1 { text-align: center; font-size: 15pt; margin-bottom: 8px; color: #1F3864; }
    .subtitle { color: #2E75B6; font-size: 10pt; text-align: center; margin-bottom: 4px; }
    .divider { border: none; border-top: 1px solid #BDD7EE; margin: 8px 0; }
    .info { font-size: 10pt; margin: 4px 0; }
    .info .label { color: #2E75B6; font-weight: bold; }
    table { width: 100%; border-collapse: collapse; margin-top: 16px; }
    td { border: 1px solid #BDD7EE; padding: 8px 12px; font-size: 10pt; vertical-align: top; }
    .row-label { background: #DEEAF1; font-weight: bold; width: 33%; text-align: center;
                 vertical-align: middle; color: #1F3864; font-size: 9.5pt; line-height: 1.4; }
    .row-content { width: 67%; }
    ul { margin: 0; padding-left: 16px; }
    li { margin-bottom: 3px; line-height: 1.5; }
  `;

  const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

  // Use sections[] built by Format Table node
  const rows = (report.sections || []).map(section => {
    const raw = String(section.content ?? 'N/A');
    let cellHtml;

    if (raw.trim().toLowerCase() === 'n/a') {
      cellHtml = 'N/A';
    } else {
      const lines = raw.split('\n')
        .map(l => l.replace(/^[\s•·\u2022\-\*]+/, '').trim())
        .filter(l => l && l.toLowerCase() !== 'n/a' && !isMetaNote(l));

      cellHtml = lines.length
        ? '<ul>' + lines.map(l => `<li>${esc(l)}</li>`).join('') + '</ul>'
        : 'N/A';
    }

    return `<tr>
      <td class="row-label">${esc(section.label).replace(/\n/g,'<br>')}</td>
      <td class="row-content">${cellHtml}</td>
    </tr>`;
  }).join('');

  return `<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"><style>${CSS}</style></head>
<body>
  <h1>${esc(report.reportTitle)}</h1>
  <p class="subtitle">${esc(report.programLine)}</p>
  <hr class="divider">
  <p class="info"><span class="label">Name: </span>${esc(report.reporter)}</p>
  <p class="info"><span class="label">Week Ending: </span>${esc(report.weekEnding)}</p>
  <hr class="divider">
  <table>${rows}</table>
</body>
</html>`;
}

// Process all items (one per reporter)
return items.map(item => ({
  json: {
    htmlContent: buildHTML(item.json),
    weekEnding:  item.json.weekEnding,
    reporter:    item.json.reporter,
    reportTitle: item.json.reportTitle,
    programLine: item.json.programLine
  }
}));

