// Prepare Email Attachment — FIXED
// - Loops over ALL items via items.map()
// - Skips any item where reporter is N/A, empty, or unknown (no blank reports)
// - Correct binary path: inputBinary.data (not inputBinary.data.data)
// ─────────────────────────────────────────────────────────────────────

const EXCLUDED = ['n/a', '', 'unknown'];

const results = [];

for (const inputItem of items) {
  const reporter = (inputItem.json?.reporter || '').trim();
  const reporterNorm = reporter.toLowerCase();

  // Skip N/A reporters — these are unassigned tickets, do not generate a report
  if (EXCLUDED.includes(reporterNorm)) {
    console.log(`[Prepare Email Attachment] Skipping N/A reporter item`);
    continue;
  }

  const inputBinary = inputItem.binary || {};

  // DocRaptor returns PDF binary under key "data" — NOT "data.data"
  const pdfBinary = inputBinary.data || inputBinary.attachment || null;

  const weekEnding = inputItem.json?.weekEnding
    || new Date().toISOString().split('T')[0];

  const fileName = `Weekly_Report_${reporter.replace(/\s+/g, '_')}_${weekEnding}.pdf`;

  if (!pdfBinary) {
    console.error(`[Prepare Email Attachment] No binary for reporter: ${reporter}`);
  }

  results.push({
    json: {
      fileName,
      weekEnding,
      reporter,
      emailSubject: `Weekly Status Report - ${weekEnding}`,
      emailReady: !!pdfBinary
    },
    binary: pdfBinary ? {
      attachment: {
        data: pdfBinary.data,
        mimeType: 'application/pdf',
        fileName
      }
    } : {}
  });
}

return results;

