// Calculate Mon–Fri this week in America/New_York
function getWeekRange() {
  const TZ = 'America/New_York';
  const nowNY = new Date(new Date().toLocaleString('en-US', { timeZone: TZ }));
  const dow = nowNY.getDay();
  const daysToMon = dow === 0 ? -6 : 1 - dow;
  const mon = new Date(nowNY);
  mon.setDate(nowNY.getDate() + daysToMon);
  mon.setHours(0, 0, 0, 0);
  const fri = new Date(mon);
  fri.setDate(mon.getDate() + 4);
  const fmt = d => [
    d.getFullYear(),
    String(d.getMonth() + 1).padStart(2, '0'),
    String(d.getDate()).padStart(2, '0')
  ].join('-');
  return { from: fmt(mon), to: fmt(fri) };
}

const { from, to } = getWeekRange();
