        description: wl.description || '',
        startDate: wl.startDate || '',
        startTime: wl.startTime || ''
      }
    });
  }
}

console.log(`[Tempo Fetch] Total: ${allWorklogs.length} worklogs across all 3 members`);
return allWorklogs.length ? allWorklogs : [{ json: { empty: true, message: 'No Tempo worklogs found for this week' } }];

