// Aggregate Tempo worklogs: hours per person per ticket this week.

const totals = {}; // { person: { issueKey: { hours, summary, descriptions: [] } } }

for (const item of items) {
  const d = item.json;
  const person = d.reporter;
  const key = d.issueKey || `UNMATCHED-${d.issueId}`;
  const hours = (d.timeSpentSeconds || 0) / 3600;

  if (!totals[person]) totals[person] = {};
  if (!totals[person][key]) {
    totals[person][key] = { hours: 0, summary: d.issueSummary || 'Unknown ticket', descriptions: [] };
  }
  totals[person][key].hours += hours;
  if (d.description) totals[person][key].descriptions.push(d.description);
}

const out = [];
for (const [person, tickets] of Object.entries(totals)) {
  let personTotal = 0;
  const ticketRows = [];
  for (const [key, info] of Object.entries(tickets)) {
    personTotal += info.hours;
    ticketRows.push({
      issueKey: key,
      summary: info.summary,
      hours: Math.round(info.hours * 100) / 100,
      descriptions: info.descriptions
    });
  }
  out.push({
    json: {
      reporter: person,
      totalHours: Math.round(personTotal * 100) / 100,
      tickets: ticketRows
    }
