// Merge Jira-derived reports with Tempo ticket coverage.
// Jira reports arrive as direct input (items).
// Tempo data is read via $() expression with graceful fallback —
// if Tempo branch produced no data, we continue with Jira-only reports.

const jiraReports = items;

// Safely read Tempo summary — returns [] if node hasn't run or is empty
let tempoSummaries = [];
try {
  tempoSummaries = $('Summarize Tempo Hours by Person').all().filter(t => !t.json.empty);
} catch (e) {
  console.log('[Merge] Tempo branch not available — proceeding with Jira data only');
}

// Safely read Flatten Issue List for issueId -> key resolution
let flattenItems = [];
try {
  flattenItems = $('Flatten Issue List').all();
} catch (e) {
  console.log('[Merge] Flatten Issue List not available for key resolution');
}

// Build issueId -> { key, summary } lookup
const issueIdToInfo = {};
for (const ji of flattenItems) {
  const id = String(ji.json.issueId || '');
  if (id) issueIdToInfo[id] = {
    key:     ji.json.issueKey,
    summary: ji.json.summary
  };
}

// Build per-person Tempo ticket map
const tempoByPerson = {};
for (const t of tempoSummaries) {
  tempoByPerson[t.json.reporter] = (t.json.tickets || []).map(ticket => ({
    ...ticket,
    issueKey:     ticket.issueKey     || issueIdToInfo[String(ticket.issueId)]?.key     || null,
    issueSummary: ticket.issueSummary || issueIdToInfo[String(ticket.issueId)]?.summary || ticket.summary || ''
  }));
}

function ticketMentioned(activitiesText, issueKey, summary) {
  if (!activitiesText) return false;
  const lower = activitiesText.toLowerCase();
  if (issueKey && lower.includes(issueKey.toLowerCase())) return true;
  if (summary) {
    const words = summary.toLowerCase().split(/\s+/).filter(w => w.length > 3);
    const hits  = words.filter(w => lower.includes(w)).length;
    if (words.length > 0 && hits / words.length >= 0.5) return true;
  }
  return false;
}

const out = [];
for (const item of jiraReports) {
  const data = { ...item.json };
  const person = data.reporter;
  const tempoTickets = tempoByPerson[person] || [];

  const existingActivities = data.activitiesPerformed || '';
  const newLines = [];

  for (const t of tempoTickets) {
    if (!t.issueSummary) continue;
    const alreadyCovered = ticketMentioned(existingActivities, t.issueKey, t.issueSummary);
    if (!alreadyCovered) {
      newLines.push(`${t.issueSummary}: Time logged this week (no detailed comment provided).`);
    }
  }

  if (newLines.length) {
    data.activitiesPerformed = existingActivities && existingActivities.trim().toLowerCase() !== 'n/a'
      ? existingActivities + '\n' + newLines.join('\n')
      : newLines.join('\n');
    console.log(`[Merge] ${person}: added ${newLines.length} Tempo-only line(s)`);
  } else {
    console.log(`[Merge] ${person}: no Tempo additions needed`);
  }

  out.push({ json: data });
}

return out;
